"use client";
import {
  useId,
  useLayoutEffect,
  useRef,
  type ReactNode,
  type CSSProperties,
} from "react";
import { folderFanLayout } from "./fan-layout";
import { createPositionMotion, type PositionMotion } from "./position-motion";
import { containerSpring } from "./physical-spring";
import { useControllableState } from "./use-controllable-state";
import "./source-tray.css";
export interface TraySource {
  id: string;
  width: number;
  height: number;
  content: ReactNode;
}
export interface SourceTrayProps {
  items: TraySource[];
  label?: ReactNode;
  closeLabel?: ReactNode;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  onSettled?: (open: boolean) => void;
  className?: string;
  style?: CSSProperties;
}
/** Renderer-neutral geometry. Hosts own assets, playback and persistence.
 * One motion writer per keyed shell; reversals retain current position/velocity. */
export function SourceTray({
  items,
  label = "Sources",
  closeLabel = "Gather",
  open: controlled,
  defaultOpen = false,
  onOpenChange,
  onSettled,
  className = "",
  style,
}: SourceTrayProps) {
  const [open, setOpen] = useControllableState(
    controlled,
    defaultOpen,
    onOpenChange,
  );
  const root = useRef<HTMLDivElement>(null),
    button = useRef<HTMLButtonElement>(null),
    nodes = useRef(new Map<string, HTMLElement>()),
    motions = useRef(new Map<string, PositionMotion>()),
    id = useId();
  const current = useRef({ open, items, onSettled });
  current.current = { open, items, onSettled };
  useLayoutEffect(() => {
    const layout = () => {
      const { open, items, onSettled } = current.current,
        w = root.current!.clientWidth,
        h = root.current!.clientHeight - 36;
      const frames = folderFanLayout(
          { x: w / 2 - 30, y: h - 24, width: 60 },
          items,
        ),
        values = [...frames.values()];
      if (!values.length) return;
      const minX = Math.min(...values.map((p) => p.x)),
        maxX = Math.max(...values.map((p) => p.x + p.width)),
        minY = Math.min(...values.map((p) => p.y));
      const scale = Math.max(
        0.05,
        Math.min(1, (w - 24) / (maxX - minX), (h - 35) / (h - 24 - minY)),
      );
      let remaining = items.length;
      for (const item of items) {
        const node = nodes.current.get(item.id);
        if (!node) continue;
        const p = frames.get(item.id)!;
        const closed = { x: w / 2 - p.width * 0.12, y: h - 55, scale: 0.24 };
        let motion = motions.current.get(item.id);
        if (!motion) {
          motion = createPositionMotion(node, closed);
          motions.current.set(item.id, motion);
        }
        motion.to(
          open
            ? {
                x: w / 2 + (p.x - w / 2) * scale,
                y: h - 24 + (p.y - (h - 24)) * scale,
                scale,
              }
            : closed,
          matchMedia("(prefers-reduced-motion: reduce)").matches,
          {
            spring: containerSpring(open ? "unfold" : "refold"),
            onFinish: () => {
              if (--remaining === 0) onSettled?.(open);
            },
          },
        );
      }
      for (const [key, motion] of motions.current)
        if (!frames.has(key)) {
          motion.dispose();
          motions.current.delete(key);
        }
    };
    layout();
    const observer = new ResizeObserver(layout);
    observer.observe(root.current!);
    return () => observer.disconnect();
  }, [open, items.map((i) => `${i.id}:${i.width}:${i.height}`).join("|")]);
  useLayoutEffect(
    () => () => {
      motions.current.forEach((m) => m.dispose());
      motions.current.clear();
    },
    [],
  );
  return (
    <div
      ref={root}
      className={`roc-source-tray ${className}`}
      style={style}
      onKeyDown={(e) => {
        if (e.key === "Escape" && open) {
          e.stopPropagation();
          setOpen(false);
          button.current?.focus();
        }
      }}
    >
      <div id={id} className="roc-tray-layer" inert={!open} aria-hidden={!open}>
        {items.map((item) => (
          <div
            key={item.id}
            ref={(node) => {
              if (node) nodes.current.set(item.id, node);
              else nodes.current.delete(item.id);
            }}
            data-tray-id={item.id}
            className="roc-tray-item"
            style={{ width: item.width, height: item.height }}
          >
            {item.content}
          </div>
        ))}
      </div>
      <button
        ref={button}
        className="roc-tray-toggle"
        type="button"
        aria-controls={id}
        aria-expanded={open}
        onClick={() => setOpen(!open)}
      >
        {open ? closeLabel : label} <span>{items.length}</span>
      </button>
    </div>
  );
}

// Extracted from Syuze; MIT Copyright (c) 2026 Songhai. See SOURCE-LICENSE.txt.
// Dense shelves fan upward from the folder; cards keep their actual dimensions.
export interface FanItem {
  id: string;
  width: number;
  height: number;
}
export function folderFanLayout(
  folder: { x: number; y: number; width: number },
  items: FanItem[],
) {
  const layout = new Map<
      string,
      { x: number; y: number; width: number; height: number; rotation: number }
    >(),
    gap = 20,
    rows: { items: FanItem[]; width: number; height: number }[] = [];
  const remaining = items
    .map((item, index) => ({ item, index }))
    .sort(
      (a, b) =>
        b.item.width * b.item.height - a.item.width * a.item.height ||
        a.index - b.index,
    )
    .map((v) => v.item);
  const columns =
    items.length <= 5 ? items.length : Math.ceil(Math.sqrt(items.length * 1.6));
  const baseWidth =
    remaining.slice(0, columns).reduce((sum, i) => sum + i.width, 0) +
    Math.max(0, columns - 1) * gap;
  while (remaining.length) {
    const budget = baseWidth * Math.pow(0.82, rows.length),
      row = [];
    let width = 0;
    while (remaining.length) {
      const item = remaining[0],
        next = width + (row.length ? gap : 0) + item.width;
      if (row.length && next > budget) break;
      row.push(remaining.shift()!);
      width = next;
    }
    rows.push({
      items: row,
      width,
      height: Math.max(...row.map((i) => i.height)),
    });
  }
  let bottom = folder.y - 24;
  for (const row of rows) {
    const center = folder.x + folder.width / 2,
      radius =
        (row.width - (row.items[0].width + row.items.at(-1)!.width) / 2) / 2,
      rise = row.items.length > 1 ? Math.min(12, row.width * 0.012) : 0;
    let x = center - row.width / 2;
    for (const item of row.items) {
      const t = radius
          ? Math.max(-1, Math.min(1, (x + item.width / 2 - center) / radius))
          : 0,
        lift = rise * (1 - t * t);
      layout.set(item.id, {
        x,
        y: bottom - item.height - lift,
        width: item.width,
        height: item.height,
        rotation: 0,
      });
      x += item.width + gap;
    }
    bottom -= row.height + 24 + rise;
  }
  return layout;
}

// Extracted from Franklin Board React worktree; MIT. See SOURCE-LICENSE.txt.
import {
  DEFAULT_SPRING,
  sampleSpring,
  type SpringOptions,
} from "./physical-spring";
type Pose = { x: number; y: number; scale: number; rotation: number };
const poseOf = (p: { x: number; y: number }): Pose => ({
  ...p,
  scale: 1,
  rotation: 0,
});
type Point = { x: number; y: number };
export interface MotionOptions {
  spring?: SpringOptions;
  preserveVelocity?: boolean;
  progressVelocity?: number;
  onFinish?: () => void;
}
export interface GeometryPose extends Pose {
  width: number;
  height: number;
}
const keys = ["x", "y", "scale", "rotation", "width", "height"] as const;
/** One transform writer per retained shell. Optional painter also drives camera/lid. */
export function createPositionMotion(
  node: HTMLElement,
  initial: Point & Partial<GeometryPose>,
  painter?: (pose: GeometryPose) => void,
) {
  let position: GeometryPose = {
      ...poseOf(initial),
      width: 0,
      height: 0,
      ...initial,
    },
    velocity: GeometryPose = {
      x: 0,
      y: 0,
      scale: 0,
      rotation: 0,
      width: 0,
      height: 0,
    };
  let target = { ...position },
    from = { ...position },
    speed = { ...velocity },
    start = 0;
  let spring = DEFAULT_SPRING,
    frame = 0,
    safety: ReturnType<typeof setTimeout> | undefined,
    done: (() => void) | undefined,
    disposed = false;
  const paint = () =>
    painter
      ? painter(position)
      : (node.style.transform = `translate3d(${position.x}px, ${position.y}px, 0) rotate(${position.rotation}deg) scale(${position.scale})`);
  const sample = () => {
    const elapsed = (performance.now() - start) / 1000;
    for (const key of keys) {
      const value = sampleSpring(
        from[key],
        target[key],
        speed[key],
        elapsed,
        spring,
      );
      position[key] = value.position;
      velocity[key] = value.velocity;
    }
  };
  // Interrupt from the last painted frame, rather than advancing unseen geometry
  // to the event timestamp. Position and velocity already share that frame.
  const stop = () => {
    if (frame) {
      cancelAnimationFrame(frame);
      frame = 0;
    }
    clearTimeout(safety);
    done = undefined;
  };
  const finish = () => {
    cancelAnimationFrame(frame);
    frame = 0;
    clearTimeout(safety);
    position = { ...target };
    velocity = { x: 0, y: 0, scale: 0, rotation: 0, width: 0, height: 0 };
    paint();
    const callback = done;
    done = undefined;
    callback?.();
  };
  const tick = () => {
    if (disposed) return;
    sample();
    paint();
    if (
      performance.now() - start > 4000 ||
      keys.every(
        (key) =>
          Math.abs(position[key] - target[key]) <
            (key === "scale" ? 0.0001 : 0.02) &&
          Math.abs(velocity[key]) < (key === "scale" ? 0.001 : 0.1),
      )
    )
      finish();
    else frame = requestAnimationFrame(tick);
  };
  paint();
  return {
    read() {
      stop();
      return { ...position };
    },
    peek() {
      return { ...position };
    },
    set(point: Point & Partial<GeometryPose>) {
      stop();
      position = {
        ...poseOf(point),
        width: position.width,
        height: position.height,
        ...point,
      };
      target = { ...position };
      velocity = { x: 0, y: 0, scale: 0, rotation: 0, width: 0, height: 0 };
      paint();
    },
    to(
      point: Point & Partial<GeometryPose>,
      reduced: boolean,
      options: MotionOptions = {},
    ) {
      if (disposed) return;
      stop();
      target = {
        ...poseOf(point),
        width: position.width,
        height: position.height,
        ...point,
      };
      done = options.onFinish;
      if (
        reduced ||
        keys.every(
          (key) => position[key] === target[key] && velocity[key] === 0,
        )
      ) {
        finish();
        return;
      }
      from = { ...position };
      speed =
        options.preserveVelocity === false
          ? { x: 0, y: 0, scale: 0, rotation: 0, width: 0, height: 0 }
          : { ...velocity };
      if (options.progressVelocity !== undefined)
        for (const key of keys)
          speed[key] = (target[key] - from[key]) * options.progressVelocity;
      spring = options.spring ?? DEFAULT_SPRING;
      start = performance.now();
      frame = requestAnimationFrame(tick);
      safety = setTimeout(finish, 4200);
    },
    finish,
    dispose() {
      disposed = true;
      stop();
    },
  };
}
export type PositionMotion = ReturnType<typeof createPositionMotion>;

// Extracted from Franklin Board React worktree; MIT. See SOURCE-LICENSE.txt.
export interface SpringOptions {
  stiffness: number;
  damping: number;
  mass: number;
}
export const DEFAULT_SPRING: SpringOptions = {
  stiffness: 400,
  damping: 38,
  mass: 1,
};
// Typed port of the retained legacy analytic spring; legacy source stays unchanged.
export function sampleSpring(
  from: number,
  to: number,
  velocity: number,
  seconds: number,
  options: Partial<SpringOptions> = {},
) {
  const {
    stiffness: k,
    damping: c,
    mass: m,
  } = { ...DEFAULT_SPRING, ...options };
  if (!(k > 0 && m > 0 && c >= 0))
    throw new RangeError("Invalid spring parameters");
  const t = Math.max(0, seconds),
    a = c / (2 * m),
    w2 = k / m,
    d = from - to;
  let x, v;
  if (Math.abs(a * a - w2) < 1e-7) {
    const b = velocity + a * d,
      e = Math.exp(-a * t);
    x = (d + b * t) * e;
    v = (b - a * (d + b * t)) * e;
  } else if (a * a < w2) {
    const w = Math.sqrt(w2 - a * a),
      b = (velocity + a * d) / w;
    const e = Math.exp(-a * t),
      cos = Math.cos(w * t),
      sin = Math.sin(w * t);
    x = e * (d * cos + b * sin);
    v = e * ((b * w - a * d) * cos - (d * w + a * b) * sin);
  } else {
    const q = Math.sqrt(a * a - w2),
      r1 = -a + q,
      r2 = -a - q;
    const b1 = (velocity - r2 * d) / (r1 - r2),
      b2 = d - b1;
    x = b1 * Math.exp(r1 * t) + b2 * Math.exp(r2 * t);
    v = r1 * b1 * Math.exp(r1 * t) + r2 * b2 * Math.exp(r2 * t);
  }
  return { position: to + x, velocity: v };
}

export type ContainerMotion =
  | "unfold"
  | "refold"
  | "pullReturn"
  | "dropGather"
  | "dropSink"
  | "lidOpen"
  | "lidClose";
/** Same parameter families as legacy src/spring.js; deterministic midpoint by default. */
export function containerSpring(
  kind: ContainerMotion,
  random = () => 0.5,
): SpringOptions {
  if (kind === "dropGather" || kind === "dropSink") {
    const mass =
      (kind === "dropGather"
        ? 0.24 + 0.08 * random()
        : 0.16 + 0.16 * random()) * 0.48;
    return { stiffness: 100, damping: 2 * Math.sqrt(100 * mass), mass };
  }
  if (kind === "unfold")
    return { stiffness: 240, damping: 20, mass: 0.8 + 0.16 * random() };
  if (kind === "refold") {
    const mass = 0.12 + 0.12 * random();
    return { stiffness: 100, damping: 2 * Math.sqrt(100 * mass), mass };
  }
  if (kind === "pullReturn")
    return { stiffness: 400, damping: 24, mass: (0.8 + 0.4 * random()) * 0.64 };
  if (kind === "lidOpen") return { stiffness: 100, damping: 10, mass: 0.64 };
  return { stiffness: 100, damping: 2 * Math.sqrt(100 * 0.32), mass: 0.32 };
}

/** Legacy document/image presentation profile: critically damped, softer opening. */
export function presentationSpring(opening: boolean): SpringOptions {
  const mass = opening ? 0.48 : 0.32;
  return { stiffness: 100, mass, damping: 2 * Math.sqrt(100 * mass) };
}

"use client";
import { useState } from "react";
/** An optional owner, not a mandatory store or application provider. */
export function useControllableState<T>(
  value: T | undefined,
  defaultValue: T,
  onChange?: (value: T) => void,
): [T, (next: T) => void] {
  const [local, setLocal] = useState(defaultValue),
    current = value === undefined ? local : value;
  return [
    current,
    (next) => {
      if (Object.is(current, next)) return;
      if (value === undefined) setLocal(next);
      onChange?.(next);
    },
  ];
}

@import "./surface.css";
.roc-source-tray {
  height: 300px;
  width: 100%;
  position: relative;
}
.roc-tray-layer {
  position: absolute;
  inset: 0;
}
.roc-tray-item {
  position: absolute;
  left: 0;
  top: 0;
  transform-origin: 0 0;
  border: 1px solid #e2dfd5;
  border-radius: var(--roc-radius, 8px);
  background: var(--roc-paper, #fcfbf8);
  box-shadow: 0 5px 16px #2221;
  overflow: hidden;
  padding: 15px;
  box-sizing: border-box;
}
.roc-tray-toggle {
  position: absolute;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  border: 1px solid #dfded7;
  border-radius: 25px;
  background: var(--roc-paper, #fcfbf8);
  padding: 9px 18px;
  font: 12px system-ui;
}

@import "./tokens.css";
@import "./animation.css";
@import "./corners.css";
@import "./responsive.css";
/* Shared surface primitives only. Tokens inherit from the host. No page reset. */
:where(
  .roc-expand,
  .roc-folder,
  .roc-sources,
  .roc-lanes,
  .roc-tabs,
  .roc-card-preview,
  .roc-image-viewport,
  .roc-voice,
  .roc-selection-toolbar,
  .roc-page-book,
  .roc-source-tray
) {
  color: var(--roc-ink, #30332e);
  font-family: inherit;
  box-sizing: border-box;
}
:where(
    .roc-expand,
    .roc-folder,
    .roc-sources,
    .roc-lanes,
    .roc-tabs,
    .roc-card-preview,
    .roc-image-viewport,
    .roc-voice,
    .roc-selection-toolbar,
    .roc-page-book,
    .roc-source-tray
  )
  * {
  box-sizing: border-box;
}
:where(
    .roc-expand,
    .roc-folder,
    .roc-sources,
    .roc-lanes,
    .roc-tabs,
    .roc-card-preview,
    .roc-image-viewport,
    .roc-voice,
    .roc-selection-toolbar,
    .roc-page-book,
    .roc-source-tray
  )
  button {
  font: inherit;
  color: inherit;
  cursor: pointer;
}
.roc-image-viewport:focus-visible,
.roc-page-book:focus-visible,
:where(
    .roc-expand,
    .roc-folder,
    .roc-sources,
    .roc-lanes,
    .roc-tabs,
    .roc-card-preview,
    .roc-image-viewport,
    .roc-voice,
    .roc-selection-toolbar,
    .roc-page-book,
    .roc-source-tray
  )
  button:focus-visible {
  outline: none;
  box-shadow: inset 0 0 0 2px var(--roc-focus, #737373) !important;
}
@media (forced-colors: active) {
  .roc-image-viewport:focus-visible,
  .roc-page-book:focus-visible,
  :where(
      .roc-expand,
      .roc-folder,
      .roc-sources,
      .roc-lanes,
      .roc-tabs,
      .roc-card-preview,
      .roc-image-viewport,
      .roc-voice,
      .roc-selection-toolbar,
      .roc-page-book,
      .roc-source-tray
    )
    button:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: -2px;
  }
}
.roc-eyebrow {
  font:
    10px/1.4 ui-monospace,
    monospace;
  letter-spacing: 0.12em;
  color: var(--roc-muted, #757b72);
}
.roc-text-button {
  border: 0;
  background: none;
  padding: 9px 0;
  font-size: 12px;
  text-align: left;
  display: inline-flex;
  gap: 20px;
  align-items: center;
}

/* Shared design tokens for ROC practice cases. Hosts may override any --roc-* token. */
:where(:root) {
  --roc-ink: #252525;
  --roc-muted: #737373;
  --roc-paper: #ffffff;
  --roc-line: #e5e5e5;
  --roc-accent: #1a1a1a;
  --roc-accent-foreground: #ffffff;
  --roc-marker: #efefef;
  --roc-focus: #737373;
  --roc-font-body: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --roc-font-heading: var(--roc-font-body);
  --roc-font-control: var(--roc-font-body);
  --roc-font-mono: ui-monospace, SFMono-Regular, Menlo, monospace;
  --roc-text-body: 13px;
  --roc-weight-control: 500;
  --roc-radius: 12px;
  --roc-space-1: 4px;
  --roc-space-2: 8px;
  --roc-space-3: 12px;
  --roc-space-4: 16px;
  --roc-space-6: 24px;
  --roc-space-8: 32px;
  --roc-control-height: 36px;
}

/* Animate UI owns presence. CSS keyframes must not compete with Motion's
   transforms/opacity or keep an exiting portal alive a second time. */
[data-roc-motion="animate-ui"][data-slot] {
  animation: none !important;
}
/* These parts use spring positions, so a CSS transition would lag the pointer. */
.roc-ui[data-slot="slider-thumb"],
.roc-ui[data-slot="slider-range"] {
  transition-property: background-color, border-color, box-shadow;
}
/* Static content stays still; interactive surfaces respond to state changes. */
:where(.roc-ui, .roc-shadcn):is(
  [data-slot="card"], [data-slot="item"], [data-slot="attachment"],
  [data-slot="table-row"], [data-slot="sidebar-menu-button"]
) {
  transition: background-color 150ms ease-out, border-color 150ms ease-out,
    box-shadow 150ms ease-out;
}
@media (prefers-reduced-motion: reduce) {
  :where(.roc-ui, .roc-shadcn):is(
    [data-slot="card"], [data-slot="item"], [data-slot="attachment"],
    [data-slot="table-row"], [data-slot="sidebar-menu-button"]
  ) { transition: none; }
}

/* Smooth squircle corners, following the visual treatment at https://corne.rs/.
   Native corner shaping keeps borders, shadows and overflowing content intact.
   Browsers without support retain the existing border-radius fallback. */
:where(
  [class^="roc-"],
  [class*=" roc-"],
  [class^="roc-"] *,
  [class*=" roc-"] *
) {
  /* ROC limits by role, informed by Apple's compact-control and surface guidance.
     These are ROC values, not platform-prescribed dimensions. Zero stays square. */
  --roc-radius-compact: min(var(--roc-radius, 9px), 8px);
  --roc-radius-control: min(var(--roc-radius, 9px), 10px);
  --roc-radius-popup: min(var(--roc-radius, 9px), 12px);
  --roc-radius-surface: min(var(--roc-radius, 12px), 20px);
}
@supports (corner-shape: squircle) {
  :where(
    [class^="roc-"],
    [class*=" roc-"],
    [class^="roc-"] *,
    [class*=" roc-"] *
  ) {
    corner-shape: var(--roc-corner-shape, squircle);
  }
}

/* Shared viewport constraints for portalled controls, including standalone consumers. */
:is(.roc-ui, .roc-shadcn)[data-slot]:is(
  [data-slot="popover-content"],
  [data-slot="hover-card-content"],
  [data-slot="tooltip-content"],
  [data-slot="select-content"],
  [data-slot="combobox-content"],
  [data-slot="dropdown-menu-content"],
  [data-slot="dropdown-menu-sub-content"],
  [data-slot="context-menu-content"],
  [data-slot="context-menu-sub-content"],
  [data-slot="menubar-content"],
  [data-slot="menubar-sub-content"]
) {
  max-inline-size: min(var(--available-width, calc(100vw - 24px)), calc(100vw - 24px));
  max-block-size: min(var(--available-height, calc(100dvh - 24px)), calc(100dvh - 24px));
  overflow: auto;
  overflow-wrap: anywhere;
  overscroll-behavior: contain;
}
@media (max-width: 640px), (pointer: coarse) {
  .roc-ui.roc-ui-button[data-slot],
  .roc-ui[data-slot="native-select"],
  .roc-shadcn[data-slot="select-trigger"] {
    min-height: 44px;
  }
  .roc-ui.roc-ui-button[data-size^="icon"] {
    width: 44px;
    height: 44px;
  }
  .roc-ui[data-slot="input"],
  .roc-ui[data-slot="textarea"],
  .roc-shadcn[data-slot="input-group-control"] {
    font-size: 16px;
  }
  .roc-ui[data-slot="input"],
  .roc-shadcn[data-slot="input-group"],
  .roc-ui[data-slot="slider"] {
    min-height: 44px;
  }
  .roc-shadcn[data-slot="input-group"] [data-slot="input-group-control"] {
    min-height: 42px;
  }
  .roc-sidebar-link,
  .roc-ui[data-slot="tabs-trigger"],
  .roc-ui[data-slot="toggle"],
  .roc-shadcn[data-slot="select-item"],
  .roc-shadcn[data-slot="combobox-item"] {
    min-height: 44px;
  }
  .roc-ui[data-slot="dropdown-menu-item"],
  .roc-ui[data-slot="dropdown-menu-checkbox-item"],
  .roc-ui[data-slot="dropdown-menu-radio-item"],
  .roc-shadcn[data-slot="context-menu-item"],
  .roc-shadcn[data-slot="menubar-item"] {
    min-height: 44px;
  }
}
